def prime_factors(n):
    """Return a dictionary of prime factors of n with their exponents."""
    factors = {}
    divisor = 2
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors[divisor] = factors.get(divisor, 0) + 1
            n //= divisor
        divisor += 1 if divisor == 2 else 2  # after 2, test only odd numbers
    if n > 1:  # n itself is prime
        factors[n] = factors.get(n, 0) + 1
    return factors

