# Determine the least common multiple (LCM) of 12, 18, and 30
# using prime‑factorisation without importing any modules.

def prime_factors(n: int) -> dict[int, int]:
    """Return a dictionary {prime: exponent} for the factorisation of n."""
    factors: dict[int, int] = {}
    divisor = 2
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors[divisor] = factors.get(divisor, 0) + 1
            n //= divisor
        divisor += 1
    if n > 1:                     # the remaining n is prime
        factors[n] = factors.get(n, 0) + 1
    return factors


# Numbers whose LCM we need
numbers = [12, 18, 30]

# Step 1‑2: collect the highest exponent for each prime that appears
max_exponents: dict[int, int] = {}
for num in numbers:
    for prime, exp in prime_factors(num).items():
        if exp > max_exponents.get(prime, 0):
            max_exponents[prime] = exp

# Step 3: compute the LCM by multiplying prime**max_exponent
lcm = 1
for prime, exp in max_exponents.items():
    lcm *= prime ** exp

# Output the final answer
print(lcm)          # 180

