intervals = [3, 4, 6, 7]

# Prime factorization of each interval
def prime_factors(n):
    """Return a dictionary of prime factors of n with their exponents."""
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:                     # n itself is prime
        factors[n] = factors.get(n, 0) + 1
    return factors

# Collect the maximum exponent for each prime across all factorizations
max_exponents = {}
for num in intervals:
    for prime, exp in prime_factors(num).items():
        max_exponents[prime] = max(max_exponents.get(prime, 0), exp)

# Compute the LCM by multiplying each prime raised to its highest exponent
lcm = 1
for prime, exp in max_exponents.items():
    lcm *= prime ** exp

# Output the result (number of school days until they are together again)
