def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_of_primes(n):
    """Find the sum of prime numbers that divide n."""
    primes = []
    for i in range(2, n + 1):
        if n % i == 0 and is_prime(i):
            primes.append(i)
    return sum(primes)

